(()=>{'use strict';const toggle=document.getElementById('launch-updates'),form=document.getElementById('lead-form');if(!toggle||!form)return;const sync=()=>{form.hidden=!toggle.checked;toggle.setAttribute('aria-expanded',String(toggle.checked))};toggle.addEventListener('change',sync);if(new URLSearchParams(location.search).has('interest'))toggle.checked=true;sync()})();

(()=>{'use strict';const frame=document.getElementById('business-login-frame');if(!frame)return;window.addEventListener('message',event=>{if(event.origin!=='https://office.mowmatter.com'||event.source!==frame.contentWindow)return;const data=event.data;if(!data||typeof data!=='object')return;if(data.type==='mm-business-login-height'&&Number.isFinite(data.height))frame.style.height=Math.min(1600,Math.max(300,data.height+32))+'px';else if(data.type==='mm-business-signed-in')location.assign('https://office.mowmatter.com/');else if(data.type==='mm-business-login-provider'&&['google','facebook'].includes(data.provider))location.assign('https://office.mowmatter.com/index.html?signin='+data.provider)})})();
